import datetime

holidays = {datetime.date(2026,10,12)}

def is_business_day(d):
    return d.weekday() < 5 and d not in holidays

def add_business_days(start, n):
    # start is the first business day of the phase; returns date of the nth business day (phase end), inclusive
    d = start
    count = 1
    while count < n:
        d += datetime.timedelta(days=1)
        if is_business_day(d):
            count += 1
    return d

def next_business_day(d):
    d += datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

start = datetime.date(2026,10,5)
print('project start weekday:', start.strftime('%A'))
assert is_business_day(start), 'start is not a business day!'

phases = [('Discovery',3), ('Build',6), ('QA',4), ('Release',1)]

cur_start = start
for name, dur in phases:
    end = add_business_days(cur_start, dur)
    print(f'{name}: start={cur_start} ({cur_start.strftime(\"%a\")}), dur={dur}, end={end} ({end.strftime(\"%a\")})')
    cur_start = next_business_day(end)

print('Launch date (end of last phase):', end)
"
